-- Temples (adds 4; the 3 existing stay)
insert into public.temples
  (id, slug, name_i18n, deity_i18n, description_i18n, district_id, address, lat, lng, cover_image_url, timings, contact, has_gaushala, featured, status)
values
  ('20000000-0000-4000-8000-000000000010','sabarimala','{"en":"Sabarimala Sree Ayyappa Temple"}','{"en":"Sree Ayyappa"}','{"en":"The famed hill shrine of Lord Ayyappa in the Western Ghats, visited during the Mandala–Makaravilakku season. Pratha is not affiliated with this temple."}','11000000-0000-4000-8000-000000000003','Sabarimala, Pathanamthitta, Kerala',9.4347,77.0817,'/images/rituals/kashi-vishwanath-aarti.jpg','{"darshan":"Seasonal — Mandala/Makaravilakku"}','{}',false,true,'published'),
  ('20000000-0000-4000-8000-000000000011','chottanikkara','{"en":"Chottanikkara Bhagavathy Temple"}','{"en":"Bhagavathy (Devi)"}','{"en":"One of Kerala’s most revered Devi temples, known for Bhagavathi Seva and relief from afflictions. Pratha is not affiliated with this temple."}','11000000-0000-4000-8000-000000000007','Chottanikkara, Ernakulam, Kerala',9.9329,76.3911,'/images/pujas/temple-hero.jpg','{"darshan":"04:00–20:00"}','{}',false,true,'published'),
  ('20000000-0000-4000-8000-000000000012','vaikom','{"en":"Vaikom Mahadeva Temple"}','{"en":"Shiva"}','{"en":"The “Kashi of the South” — an ancient Shiva temple renowned for homams, shanti pujas, and the Ashtami festival. Pratha is not affiliated with this temple."}','11000000-0000-4000-8000-000000000005','Vaikom, Kottayam, Kerala',9.7475,76.3964,'/images/pujas/rudra-abhishekam.jpg','{"darshan":"04:00–20:30"}','{}',false,true,'published'),
  ('20000000-0000-4000-8000-000000000013','ambalappuzha','{"en":"Ambalappuzha Sree Krishna Temple"}','{"en":"Sree Krishna"}','{"en":"Home of the legendary Ambalappuzha Palpayasam — a milk porridge offering with centuries of tradition. Pratha is not affiliated with this temple."}','11000000-0000-4000-8000-000000000004','Ambalappuzha, Alappuzha, Kerala',9.3858,76.3692,'/images/pujas/maha-sudarshana.jpg','{"darshan":"03:00–20:00"}','{}',false,false,'published')
on conflict (id) do nothing;

