-- Puja offerings — spanning every offering_kind, several deities and the
-- nakshatra-lord→worship mapping used by kundali-ask.
insert into public.puja_offerings
  (id, slug, temple_id, name_i18n, description_i18n, significance_i18n, category_id,
   offering_kind, price, currency, requires_sankalpa, requires_nakshatra, available_days,
   lead_time_days, priest_name, duration_min, gaushala_id, image_url, popular, status)
values
  ('40000000-0000-4000-8000-000000000010','ganapathi-homam-guruvayur','20000000-0000-4000-8000-000000000001','{"en":"Ganapathi Homam"}','{"en":"A fire ritual invoking Lord Ganesha to remove obstacles before new beginnings, exams, or undertakings."}','{"en":"Recommended for Ketu-ruled nakshatras and for clearing graha dosha before auspicious starts."}','07574918-8016-4bad-9a5d-ca5e837b3b44','special',25100,'INR',true,true,'{0,1,2,3,4,5,6}',2,'Temple tantric team',90,null,'/images/pujas/maha-sudarshana.jpg',true,'published'),
  ('40000000-0000-4000-8000-000000000011','mula-nakshatra-shanti','20000000-0000-4000-8000-000000000012','{"en":"Mula Nakshatra Shanti Puja"}','{"en":"Gandmool shanti for those born under Mula — pacifies Ketu afflictions and honours the nakshatra deity."}','{"en":"Performed for births in Mula and other gandmool nakshatras; traditionally done in the first year or on the janma nakshatra day."}','07574918-8016-4bad-9a5d-ca5e837b3b44','special',55100,'INR',true,true,'{0,1,2,3,4,5,6}',3,'Vaikom tantric team',120,null,'/images/pujas/rudra-abhishekam.jpg',true,'published'),
  ('40000000-0000-4000-8000-000000000012','navagraha-shanti-vaikom','20000000-0000-4000-8000-000000000012','{"en":"Navagraha Shanti Homam"}','{"en":"Propitiation of all nine grahas for planetary afflictions indicated by the birth chart."}','{"en":"Balances graha dosha; suited when the nakshatra lord or dasha lord is afflicted."}','07574918-8016-4bad-9a5d-ca5e837b3b44','special',75100,'INR',true,true,'{0,1,2,3,4,5,6}',3,'Vaikom tantric team',150,null,'/images/pujas/maha-sudarshana.jpg',true,'published'),
  ('40000000-0000-4000-8000-000000000013','bhagavathi-seva-chottanikkara','20000000-0000-4000-8000-000000000011','{"en":"Bhagavathi Seva"}','{"en":"An evening pooja to the Goddess with lamps, flowers, and panchamrita — for protection and removal of negativities."}','{"en":"Especially efficacious for Rahu/Venus afflictions and for devotees of Devi nakshatras."}','07574918-8016-4bad-9a5d-ca5e837b3b44','special',110100,'INR',true,true,'{0,1,2,3,4,5,6}',5,'Bhagavathi seva priest',180,null,'/images/pujas/temple-hero.jpg',true,'published'),
  ('40000000-0000-4000-8000-000000000014','mrityunjaya-homam-vaikom','20000000-0000-4000-8000-000000000012','{"en":"Mrityunjaya Homam"}','{"en":"The great healing homam to Lord Shiva — for health, longevity, and relief from fear of untimely harm."}','{"en":"Traditionally performed for the sick, for elders, and on janma nakshatra days."}','07574918-8016-4bad-9a5d-ca5e837b3b44','special',150100,'INR',true,true,'{0,1,2,3,4,5,6}',5,'Vaikom tantric team',180,null,'/images/pujas/rudra-abhishekam.jpg',false,'published'),
  ('40000000-0000-4000-8000-000000000015','udayasthamana-guruvayur','20000000-0000-4000-8000-000000000001','{"en":"Udayasthamana Pooja"}','{"en":"The crown of Guruvayur vazhipadus — a full day of worship from dawn to dusk, dawn opening to night closing."}','{"en":"Among the most sought-after offerings at Guruvayur; booked months ahead."}','07574918-8016-4bad-9a5d-ca5e837b3b44','vazhipadu',1500100,'INR',true,true,'{0,1,2,3,4,5,6}',30,'Devaswom priests',720,null,'/images/pujas/temple-hero.jpg',true,'published'),
  ('40000000-0000-4000-8000-000000000016','neyvilakku-guruvayur','20000000-0000-4000-8000-000000000001','{"en":"Neyvilakku (Ghee Lamp)"}','{"en":"Lighting a ghee lamp before the deity — a simple daily offering of light and devotion."}','{"en":"A gentle everyday vazhipadu; many devotees keep a standing weekly offering."}','ce83b749-d78b-432b-a818-83b15462f31e','ghee_offering',5100,'INR',true,false,'{0,1,2,3,4,5,6}',1,null,15,null,'/images/rituals/kashi-vishwanath-aarti.jpg',false,'published'),
  ('40000000-0000-4000-8000-000000000017','palpayasam-ambalappuzha','20000000-0000-4000-8000-000000000013','{"en":"Palpayasam Nivedyam"}','{"en":"The famous Ambalappuzha milk-porridge offering, prepared in the temple’s own kitchens and distributed as prasadam."}','{"en":"Legend says the deity himself comes for the noon palpayasam — a beloved Krishna offering."}','ce83b749-d78b-432b-a818-83b15462f31e','vazhipadu',10100,'INR',true,false,'{0,1,2,3,4,5,6}',2,null,30,null,'/images/pujas/maha-sudarshana.jpg',true,'published'),
  ('40000000-0000-4000-8000-000000000018','sahasranama-archana-padmanabha','20000000-0000-4000-8000-000000000003','{"en":"Vishnu Sahasranama Archana"}','{"en":"Chanting of the thousand names of Vishnu with flowers at the reclining Lord’s feet."}','{"en":"Suited for Jupiter and Moon nakshatras, and for seekers of peace and prosperity."}','ce83b749-d78b-432b-a818-83b15462f31e','archana',5100,'INR',true,true,'{0,1,2,3,4,5,6}',1,'Temple priest',30,null,'/images/pujas/temple-hero.jpg',true,'published'),
  ('40000000-0000-4000-8000-000000000019','graha-peeda-archana-chottanikkara','20000000-0000-4000-8000-000000000011','{"en":"Graha Peeda Parihara Archana"}','{"en":"An archana to the Goddess for relief from planetary afflictions — Shani, Rahu, or Ketu periods."}','{"en":"Frequently chosen during Sade Sati or adverse dasha/transit periods."}','07574918-8016-4bad-9a5d-ca5e837b3b44','archana',20100,'INR',true,true,'{0,1,2,3,4,5,6}',2,'Bhagavathi seva priest',45,null,'/images/pujas/temple-hero.jpg',false,'published'),
  ('40000000-0000-4000-8000-000000000020','gau-pooja-sanctuary','20000000-0000-4000-8000-000000000001','{"en":"Gau Pooja at the Sanctuary"}','{"en":"Worship of the cow as Go Mata — feeding, aarti, and touching the herd’s feet for blessings."}','{"en":"Go seva is recommended for Saturn/Mercury nakshatras and as an act of daily punya."}','fa4ef683-ba98-43c7-93bb-29448ea0aa4f','gau_pooja',11100,'INR',true,false,'{0,1,2,3,4,5,6}',1,'Gaushala caretakers',45,'30000000-0000-4000-8000-000000000001','/images/animals/nandini.jpg',false,'published'),
  ('40000000-0000-4000-8000-000000000021','gau-grasam-sanctuary','20000000-0000-4000-8000-000000000001','{"en":"Gau Grasam (First Feed Offering)"}','{"en":"Offer the day’s first feed to the rescued herd — grass, jaggery, and grain in your name."}','{"en":"A small but beloved daily seva; prasadam of the act is shared with the herd."}','fa4ef683-ba98-43c7-93bb-29448ea0aa4f','gau_grasam',5100,'INR',true,false,'{0,1,2,3,4,5,6}',1,'Gaushala caretakers',20,'30000000-0000-4000-8000-000000000001','/images/animals/gauri.jpg',false,'published'),
  ('40000000-0000-4000-8000-000000000022','shani-parihara-deepam-vaikom','20000000-0000-4000-8000-000000000012','{"en":"Shani Parihara Deepam"}','{"en":"A Saturday lamp offering to pacify Lord Shani during Sade Sati, Ashtama Shani, or Saturn dasha."}','{"en":"Performed only on Saturdays — the day ruled by Shani."}','07574918-8016-4bad-9a5d-ca5e837b3b44','special',30100,'INR',true,true,'{6}',2,'Vaikom tantric team',60,null,'/images/pujas/rudra-abhishekam.jpg',false,'published')
on conflict (id) do nothing;

-- Festivals (3 more alongside Onam)
insert into public.festivals (id, slug, name_i18n, summary_i18n, body_i18n, month_hint, cover_image_url, featured, status)
values
  ('60000000-0000-4000-8000-000000000010','thrissur-pooram','{"en":"Thrissur Pooram"}','{"en":"The “festival of festivals” — caparisoned elephants, kudamattam, and the thunder of Panchari Melam on the Thekkinkadu maidan."}','{"en":"Held each year at Vadakkunnathan Temple, Thrissur, on the Pooram nakshatra of Medam. Two devaswom sides — Paramekkavu and Thiruvambady — compete in grandeur."}','April–May (Medam)','/images/rituals/kashi-vishwanath-aarti.jpg',true,'published'),
  ('60000000-0000-4000-8000-000000000011','vishu','{"en":"Vishu"}','{"en":"The Malayalam new year — Vishukkani at dawn, Vishukkaineettam for children, and a day of new beginnings."}','{"en":"Kani-kaanal: viewing auspicious first sight of lamps, rice, gold, and konnappoo before dawn on Medam 1."}','April (Medam 1)','/images/pujas/temple-hero.jpg',true,'published'),
  ('60000000-0000-4000-8000-000000000012','mandala-pooja','{"en":"Mandala Pooja"}','{"en":"The 41-day Sabarimala austerity season ending in Mandala Pooja — a season of vratam, bhajans, and pilgrimage."}','{"en":"Vrishchikam 1 to Dhanu 11: devotees observe the mandala vratam before the pilgrimage to Sannidhanam."}','November–December','/images/pujas/rudra-abhishekam.jpg',false,'published')
on conflict (id) do nothing;

-- Events (4 more; all upcoming)
insert into public.events (id, slug, title_i18n, description_i18n, activities_i18n, category_id, temple_id, venue_name, venue_address, starts_at, ends_at, is_free, organiser, featured, status)
values
  ('70000000-0000-4000-8000-000000000010','chakyar-koothu-vadakkunnathan','{"en":"Chakyar Koothu: Stories of the Epics"}','{"en":"The ancient temple storytelling art — wit, Sanskrit, and satire performed inside the koothambalam."}','{"en":["Koothu performance","Introduction to the art form","Q&A with the artist"]}','f4c1d864-3cce-4517-ac27-28949eff71f4','20000000-0000-4000-8000-000000000001','Koothambalam, Vadakkunnathan Temple','Thrissur, Kerala','2026-11-14T13:00:00+00:00','2026-11-14T16:00:00+00:00',true,'{"name":"Pratha Cultural Trust"}',true,'published'),
  ('70000000-0000-4000-8000-000000000011','velakali-ambalappuzha','{"en":"Velakali Demonstration"}','{"en":"The martial dance of the Nair warriors, performed with sword and shield to panchavadyam rhythms."}','{"en":["Velakali performance","Panchavadyam ensemble","Photo session"]}','b5c66458-9c0e-4e74-ac23-6593a26c27bf','20000000-0000-4000-8000-000000000013','Ambalappuzha Temple Grounds','Ambalappuzha, Alappuzha','2026-11-21T12:00:00+00:00','2026-11-21T15:00:00+00:00',true,'{"name":"Ambalappuzha Cultural Forum"}',false,'published'),
  ('70000000-0000-4000-8000-000000000012','panchari-melam-night','{"en":"A Night of Panchari Melam"}','{"en":"An evening ensemble of chenda, kombu, and ilathalam — Kerala’s grandest percussion concert."}','{"en":["Panchari Melam (4 kaalam)","Elanjithara Melam excerpt","Meet the melam masters"]}','f4c1d864-3cce-4517-ac27-28949eff71f4',null,'Thekkinkadu Maidan','Thrissur, Kerala','2026-12-05T14:00:00+00:00','2026-12-05T17:00:00+00:00',true,'{"name":"Pratha Cultural Trust"}',true,'published'),
  ('70000000-0000-4000-8000-000000000013','sopana-sangeetham-vaikom','{"en":"Sopana Sangeetham Evening"}','{"en":"Sacred temple music sung to the rhythm of the edakka — the devotional voice of Kerala’s sanctums."}','{"en":["Sopana sangeetham concert","Talk on temple music traditions"]}','f4c1d864-3cce-4517-ac27-28949eff71f4','20000000-0000-4000-8000-000000000012','Vaikom Temple Nadapandal','Vaikom, Kottayam','2026-11-12T13:30:00+00:00','2026-11-12T15:30:00+00:00',true,'{"name":"Vaikom Arts Society"}',false,'published')
on conflict (id) do nothing;

